<script setup lang="ts">
import type { DraftRule, Operator } from './model'
import { operators, predicate, values } from './model'
import { t } from '@/i18n'
const props = defineProps<{ rule: DraftRule }>()
function setExpression(event: Event) {
  const value = (event.target as HTMLSelectElement).value
  if (value === 'advisory_only') { props.rule.expressivity = 'advisory_only'; props.rule.predicate = null; props.rule.enforcement = 'advisory' }
  else { props.rule.expressivity = 'deterministic'; props.rule.predicate = [predicate('op_in')]; props.rule.enforcement = 'runtime' }
}
function changeOp(index: number, event: Event) {
  const value = (event.target as HTMLSelectElement).value as Operator
  if (props.rule.predicate && operators.includes(value)) props.rule.predicate[index] = predicate(value)
}
</script>
<template><div class="panel min-w-0"><div class="panel-header"><div><h2 class="panel-title">{{ t('ruleForm.title') }}</h2><p class="panel-kicker">{{ t('ruleForm.kicker') }}</p></div></div><div class="panel-body space-y-5 text-xs">
<div class="grid gap-3 sm:grid-cols-3"><label class="field"><span class="field-label">{{ t('ruleFields.id') }}</span><input v-model="rule.id" class="control" /></label><label class="field"><span class="field-label">{{ t('ruleFields.dimension') }}</span><input v-model="rule.dimension" class="control" /></label><label class="field"><span class="field-label">{{ t('ruleFields.level') }}</span><input v-model.number="rule.level" type="number" min="0" step="1" class="control" /></label></div>
<div class="grid gap-3 sm:grid-cols-3"><label class="field"><span class="field-label">{{ t('ruleFields.expressivity') }}</span><select :value="rule.expressivity" class="control" @change="setExpression"><option value="deterministic">deterministic</option><option value="advisory_only">advisory_only</option></select></label><label class="field"><span class="field-label">{{ t('ruleFields.policyClass') }}</span><select v-model="rule.policy_class" class="control"><option>security</option><option>engineering</option></select></label><label class="field"><span class="field-label">{{ t('ruleFields.enforcement') }}</span><select v-model="rule.enforcement" class="control"><option v-if="rule.expressivity === 'advisory_only'">advisory</option><template v-else><option>runtime</option><option>ci</option><option>server</option></template></select></label></div>
<div class="grid gap-3 sm:grid-cols-4"><label class="field"><span class="field-label">{{ t('ruleFields.onHit') }}</span><select v-model="rule.on_hit" class="control"><option>deny</option><option>confirm</option><option>log</option></select></label><label class="field"><span class="field-label">{{ t('ruleFields.scope') }}</span><select v-model="rule.scope" class="control"><option>project</option><option>session</option></select></label><label class="field"><span class="field-label">{{ t('ruleFields.owner') }}</span><select v-model="rule.owner" class="control"><option>human</option><option>agent</option></select></label><label class="field"><span class="field-label">{{ t('ruleForm.ttl') }}</span><input :value="rule.ttl ?? ''" :placeholder="t('ruleForm.ttlPlaceholder')" class="control" @input="rule.ttl = ($event.target as HTMLInputElement).value || null" /></label></div>
<label class="field"><span class="field-label">{{ t('ruleFields.narrativeField') }}</span><textarea v-model="rule.narrative" rows="3" class="control" /></label>
<fieldset class="space-y-3 rounded-md border border-border p-3"><legend class="px-1 font-semibold">{{ t('ruleFields.predicateField') }}</legend><p class="text-muted-foreground">{{ t('ruleForm.predicateNote') }}</p><p v-if="rule.expressivity === 'advisory_only'" class="text-muted-foreground">{{ t('ruleForm.advisoryNote') }}</p><template v-else><div v-for="(p, i) in rule.predicate" :key="i" class="space-y-2 rounded-md border border-border p-3"><div class="flex flex-wrap items-center gap-2"><label class="field flex-1"><span class="field-label">{{ t('ruleForm.operator') }}</span><select :value="p.op" class="control" @change="changeOp(i, $event)"><option v-for="op in operators" :key="op">{{ op }}</option></select></label><button type="button" class="mt-4 rounded border border-border px-2 py-1 hover:bg-accent" @click="rule.predicate?.splice(i, 1)">{{ t('ruleForm.removeCondition') }}</button></div><p class="text-muted-foreground">{{ Object.keys(p.args)[0] }}</p><div v-for="(_, j) in values(p)" :key="j" class="flex gap-2"><input v-model="values(p)[j]" :aria-label="t('ruleForm.argLabel', { condition: i + 1, arg: j + 1 })" class="control min-w-0 flex-1" /><button type="button" class="rounded border border-border px-2 hover:bg-accent" @click="values(p).splice(j, 1)">{{ t('ruleForm.removeItem') }}</button></div><button type="button" class="rounded border border-border px-2 py-1 hover:bg-accent" @click="values(p).push('')">{{ t('ruleForm.addItem') }}</button></div><button type="button" class="rounded border border-border px-2 py-1 hover:bg-accent" @click="rule.predicate?.push(predicate('op_in'))">{{ t('ruleForm.addCondition') }}</button></template></fieldset>
<fieldset class="grid gap-3 rounded-md border border-border p-3 sm:grid-cols-2"><legend class="px-1 font-semibold">{{ t('ruleFields.sourceField') }}</legend><label v-for="key in (['repo', 'rev', 'path', 'section', 'lines', 'quote'] as const)" :key="key" class="field"><span class="field-label">{{ key }}</span><textarea v-if="key === 'quote'" v-model="rule.source[key]" rows="3" class="control" /><input v-else v-model="rule.source[key]" class="control" /></label></fieldset><label class="field"><span class="field-label">{{ t('ruleFields.probeField') }}</span><textarea v-model="rule.probe" rows="3" class="control" /></label>
</div></div></template>
<style scoped>.control { width: 100%; border: 1px solid hsl(var(--input)); border-radius: 6px; background: hsl(var(--background)); padding: 7px 9px; color: hsl(var(--foreground)); }</style>
